Creating new array literals for styles inside `renderItem` causes unnecessary re-renders of list items. Each render creates new array references, preventing React reconciliation optimizations.

**Suggested fix:**
Move style arrays outside the component or renderItem function:

```typescript
const flexRowStyle = [styles.flexRow];
const flex2ColumnStyle = [styles.flex2, styles.flexColumn, styles.justifyContentEvenly];
const minMaxHeightStyle = [styles.flexRow, styles.alignItemsCenter, styles.minHeight5, styles.maxHeight5];

const renderItem: ListRenderItem<Transaction> = ({item}) => {
    // ...
    return (
        <View style={expenseCardStyle}>
            <View style={flexRowStyle}>
                {/* ... */}
                <View style={flex2ColumnStyle}>
                    <View style={minMaxHeightStyle}>
                        {/* ... */}
                    </View>
                </View>
            </View>
        </View>
    );
};
```

